using GraphApi.Models.ANM.Anuncios;namespace GraphApi.Services.ANM.Anuncios{    /// <summary>    /// Define las operaciones de negocio y persistencia para Anuncios.    /// </summary>    public interface IAnunciosService    {        /// <summary>        /// Obtiene la lista de Anuncios con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadAnuncios>> GetAnuncios(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de Anuncios con filtros opcionales.        /// </summary>        /// <param name="anuncioID">Filtro opcional para AnuncioID.</param>        /// <param name="titulo">Filtro opcional para Titulo.</param>        /// <param name="contenido">Filtro opcional para Contenido.</param>        /// <param name="fechaPublicacion">Filtro opcional para FechaPublicacion.</param>        /// <param name="vigenteHasta">Filtro opcional para VigenteHasta.</param>        /// <param name="tipoAnuncioID">Filtro opcional para TipoAnuncioID.</param>        /// <param name="tipoAnuncio">Filtro opcional para TipoAnuncio.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetAnunciosDynamic(            int? anuncioID,            string? titulo,            string? contenido,            DateTime? fechaPublicacion,            DateTime? vigenteHasta,            int? tipoAnuncioID,            string? tipoAnuncio,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo Anuncio.        /// </summary>        /// <param name="objInput">Datos para crear el Anuncio.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadAnuncios> CreateAnuncios(            clCreateAnuncios objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un Anuncio.        /// </summary>        /// <param name="objInput">Datos para actualizar el Anuncio, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadAnuncios?> UpdateAnuncios(            clUpdateAnuncios objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un Anuncio por su ID.        /// </summary>        /// <param name="nAnunciosID">ID del Anuncio a eliminar.</param>        Task<bool> DeleteAnuncios(int nAnunciosID);    }}